__NUXT_JSONP__("/posts/transitioning-graphic-design-front-end-development", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B){return {data:[{post:{slug:t,description:h,title:"Transitioning from graphic design to front-end development",type:e,imgCover:t,tags:["miscs",e],createdAt:"2019-01-07T00:00:00.000Z",toc:[{id:u,depth:i,text:v},{id:w,depth:i,text:x},{id:f,depth:i,text:y}],body:{type:z,children:[{type:b,tag:d,props:{},children:[{type:a,value:h}]},{type:a,value:c},{type:a,value:c},{type:b,tag:j,props:{id:u},children:[{type:b,tag:k,props:{ariaHidden:l,href:"#situation-assessment",tabIndex:m},children:[{type:b,tag:n,props:{className:[o,p]},children:[]}]},{type:a,value:v}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"2019 is here and it’s always a good time for introspection and to assign ourselves new directions.\nFor my part, it’s been a few month already that I took the decision to focus on an intense front-end development learning. Why ?"}]},{type:a,value:c},{type:b,tag:"ul",props:{},children:[{type:a,value:c},{type:b,tag:g,props:{},children:[{type:a,value:"I tend to feel more challenged and excited when I build something coding than designing, it has to do with scaffolding and organising bricks of logic that form an overall working interface"}]},{type:a,value:c},{type:b,tag:g,props:{},children:[{type:a,value:"I want to handle how things looks inside a concrete usable product, not only through the graphic layouts"}]},{type:a,value:c},{type:b,tag:g,props:{},children:[{type:a,value:"It’s not hardware-dependent, therefore, the workflow is “flowing” better as IDE + browsers are the main work tools."}]},{type:a,value:c},{type:b,tag:g,props:{},children:[{type:a,value:"Jobs market perspectives are higher in this field and will continue growing"}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"A year ago, I wrote something about being picky with the chosen fields to avoid burn-out."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"I’ve been applying this so far, but I’m eager now to go towards more complicated things to build such as progressive web apps or static sites. Those kind of stuffs requires to get hands way deeper in javascript methods, javascript frameworks, and a lot of third party services as the industry is evolving this way."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"It's way above coding a simple landing page or build a Wordpress theme with my current skillset."}]},{type:a,value:c},{type:b,tag:j,props:{id:w},children:[{type:b,tag:k,props:{ariaHidden:l,href:"#learning-path",tabIndex:m},children:[{type:b,tag:n,props:{className:[o,p]},children:[]}]},{type:a,value:x}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Just after finished the short 3D film that took me 10 working months, I decided to focus my energy to rework on all the javascript basics."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"For 2 months, I used Freecodecamp on a daily basis until I got my \"JavaScript Algorithms and Data Structures” certification. Freecodecamp is a wonderful free learning platform that covers a lot of topics. It is based on everyday practice, and we get small problems to solve in an online code editor."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Just after this, I enrolled in vueschool.io, a learning platform dedicated on Vue.js. I completed the main course and it’s challenging to follow as the instructor goes at a very fast pace + the presented project (a complete forum) is quite complex. Nevertheless, It’s well organised, and the interface is neat."}]},{type:a,value:c},{type:b,tag:j,props:{id:f},children:[{type:b,tag:k,props:{ariaHidden:l,href:"#next",tabIndex:m},children:[{type:b,tag:n,props:{className:[o,p]},children:[]}]},{type:a,value:y}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Now, I’ve barely have the basics to start and I plan to work on side-projects to get a deep comprehension of the whole modern front-end tooling. The goal is to land 4\u002F5 projects, push them on my Github and build a solid portfolio to pretend applying for a junior position\u002Fjob in the industry."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Beside this, I don’t plan to completely drop my design skills : I’m aware that having a strong design background is a strength and I can take advantage of this so I'll still work on designs, at least to maintain what I’ve built so far. But focus is on web development this year."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"I’ll make another assessment in a year or so, so that I could keep track on this planned transition and how things happens."}]}]},excerpt:{type:z,children:[{type:b,tag:d,props:{},children:[{type:a,value:h}]}]},dir:"\u002Fposts",path:"\u002Fposts\u002Ftransitioning-graphic-design-front-end-development",extension:".md",updatedAt:"2025-10-10T15:29:17.529Z"},relatedPosts:[{title:"Giskard Hub: behind the LLMs evaluation platform",type:e,imgCover:"the-giskard-hub",tags:[f,q,r,s,"fastApi",A,e],createdAt:"2026-03-16T00:00:00.000Z",path:"\u002Fposts\u002Fthe-giskard-hub"},{title:"Red Teamer: Building a Button-Based AI Chatbot Game",type:e,imgCover:"red-teamer-building-a-button-based-ai-chatbot-game",tags:["game",f,B,q,r,s,"cinema 4D",A,e],createdAt:"2025-09-07T00:00:00.000Z",path:"\u002Fposts\u002Fred-teamer-building-a-button-based-ai-chatbot-game"},{title:"Explainer Motion Design Journey",type:e,imgCover:"explainer-motion-design-journey",tags:["motion graphics","after effects","video",e],createdAt:"2025-06-07T00:00:00.000Z",path:"\u002Fposts\u002Fexplainer-motion-design-journey"},{title:"Building a narrative game with Next.js and AI",type:e,imgCover:"building-a-narrative-game-with-nextjs-and-ai",tags:["games",f,B,q,r,s,"dzine",e],createdAt:"2025-03-20T00:00:00.000Z",path:"\u002Fposts\u002Fbuilding-a-narrative-game-whith-nextjs-and-ai"}]}],fetch:[{counter:24},{counter:72}],mutations:[]}}("text","element","\n","p","article","next","li","On changing career direction..",2,"h2","a","true",-1,"span","icon","icon-link","Tailwind","Figma","devs","transitioning-graphic-design-front-end-development","situation-assessment","Situation assessment","learning-path","Learning path","Next","root","AI","framer-motion")));